//! Preset variables and classes, and kebab-casing; every expected value was produced by WordPress 7.1.5.
//!
//! Generated by `.superpowers/gen_presets.py`; edit the generator, not the cases.

#![allow(unused_variables)] // Each case builds every input, whether its call uses it or not.

mod support;

use std::rc::Rc;

use speedyspec_hooks::{Key, Value};
use speedyspec_wp_theme_json::css::Declaration;
use speedyspec_wp_theme_json::presets::fluid::FluidFontSize;
use speedyspec_wp_theme_json::presets::kebab::to_kebab_case;
use speedyspec_wp_theme_json::presets::vars::{
    compute_preset_classes, compute_preset_vars, compute_theme_vars,
};
use speedyspec_wp_theme_json::{MemoryGlobalSettings, ThemeJsonCodec, construct};
use speedyspec_wp_theme_json_contracts::Origin;
use support::{assert_php_same as assert_php_eq, block, deps, json, st};

/// Declarations as WordPress's list of `name`/`value` arrays.
fn decls(list: Vec<Declaration>) -> Value {
    Value::Array(
        list.into_iter()
            .enumerate()
            .map(|(i, d)| {
                (
                    Key::Int(i as i64),
                    Value::Array(vec![
                        (Key::Str("name".into()), Value::Str(d.name)),
                        (Key::Str("value".into()), d.value),
                    ]),
                )
            })
            .collect(),
    )
}

